const icons={home:'<path d="m3 10 9-7 9 7v10H6V10"/><path d="M10 20v-7h4v7"/>',car:'<path d="m4 10 2-6h12l2 6M3 10h18v8H3zM5 18v3m14-3v3M6 14h2m8 0h2"/>',users:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-4c0-5 12-5 12 0v4M16 4c5 0 5 6 0 6m3 4c3 1 3 4 3 7"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18m-13 4h1m3 0h1m3 0h1m-9 3h1m3 0h1"/>',tool:'<path d="m14 4 1 4 4 1 3-3a7 7 0 0 1-9 9l-7 7-4-4 7-7a7 7 0 0 1 2-9z"/>',bell:'<path d="M5 17h14l-2-4V8a5 5 0 0 0-10 0v5zM10 21h4"/>',chart:'<path d="M4 21V11h3v10m4 0V5h3v16m4 0V2h3v19"/>',key:'<circle cx="15" cy="8" r="6"/><path d="m11 13-8 8v-4h4v-4"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/>',plus:'<path d="M12 4v16M4 12h16"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.car}</svg>`;
const uid=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const future=n=>{let d=new Date();d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const seed=[['Toyota Corolla','AA-123-BF','Berline','K. Kouamé','Affecté',28450,'sedan'],['Hyundai Tucson','AA-456-BF','SUV','A. Koné','Affecté',41230,'grey-suv'],['Peugeot 508','AA-789-BF','Berline','F. Niamké','Affecté',19875,'grey-suv'],['Kia Sportage','AA-321-BF','SUV','','Disponible',12340,'suv'],['Renault Mégane','AA-654-BF','Berline','S. Diarra','Affecté',36120,'sedan'],['Toyota RAV4','AA-987-BF','SUV','','En entretien',48560,'white-suv'],['Honda Accord','AA-159-BF','Berline','M. Bamba','Affecté',22410,'sedan'],['Peugeot 3008','AA-753-BF','SUV','','Disponible',30900,'suv']];
const initial=()=>({schema:1,vehicles:seed.map((v,i)=>({id:String(i+1),name:v[0],plate:v[1],category:v[2],person:v[3],status:v[4],km:v[5],image:v[6],insurance:future([40,55,93,75,120,65,100,95][i])})),maintenance:[{id:'m1',vehicle:'6',title:'Entretien périodique',date:future(3),cost:45000,done:false},{id:'m2',vehicle:'5',title:'Vidange + contrôle',date:future(16),cost:30000,done:false},{id:'m3',vehicle:'8',title:'Révision annuelle',date:future(29),cost:60000,done:false}],reservations:[]});
let state,storageOK=true,loadError=false;
state=Fleet.validate({schema:2,vehicles:[],maintenance:[],reservations:[],deletedVehicles:[],exitedVehicles:[],accidents:[]});
function save(){return window.CloudBridge?window.CloudBridge.persist(state):false;}
const routes=[['dashboard','Tableau de bord','home'],['vehicles','Véhicules','car'],['assignments','Affectations','users'],['reservations','Réservations','calendar'],['maintenance','Entretiens','tool'],['deadlines','Échéances','bell'],['accidents','Sinistres et accidents','shield'],['exits','Sorties du parc','car'],['reports','Rapports','chart'],['access','Utilisateurs et droits d’accès','users']];
let exitTab='active';
let page='dashboard',filter='',query='',dueTab='maintenance';
const fmt=n=>Number(n).toLocaleString('fr-FR'),date=d=>d?new Date(d+'T12:00:00').toLocaleDateString('fr-FR',{day:'numeric',month:'short',year:'numeric'}):'—';
const days=d=>Math.round((new Date(d+'T12:00:00')-new Date(today()+'T12:00:00'))/86400000);
const relative=d=>days(d)<0?`${Math.abs(days(d))} j de retard`:days(d)===0?"Aujourd’hui":`dans ${days(d)} jours`;
const vehicle=id=>state.vehicles.find(v=>v.id===id);
const photo=v=>`<img src="${esc(v.photo||`assets/${v.status==='En entretien'?'repair-compact':v.image||'sedan'}.png`)}" class="${v.photo?'real-photo':''}" alt="${esc(v.photo?'Photo de '+v.name:v.status==='En entretien'?'Véhicule en entretien, capot ouvert':'Illustration du véhicule')}">`;

const kmLabel=v=>v===null||v===undefined?'Non renseigné':fmt(v)+' km';
const vehicleAge=d=>{if(!d)return 'Non renseigné';const now=new Date(today()+'T12:00:00'),start=new Date(d+'T12:00:00');if(start>now)return 'Mise en circulation à venir';let years=now.getFullYear()-start.getFullYear();if(now.getMonth()<start.getMonth()||now.getMonth()===start.getMonth()&&now.getDate()<start.getDate())years--;return years+' an'+(years>1?'s':'');};
const status=s=>`<span class="status ${s==='Disponible'?'available':s==='En entretien'?'maintenance':s==='À vérifier'?'unknown':s==='Accidenté / Immobilisé'?'accident':''}"><i></i>${esc(s)}</span>`;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function head(title,sub,action=''){return `<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div>${action||`<div class="date">${icon('calendar')}${new Date().toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</div>`}</div>`}
const addButton=(label,type)=>`<button class="primary" data-add="${type}">${icon('plus')}${label}</button>`;
function filtered(){return state.vehicles.filter(v=>(!filter||v.status===filter)&&(!query||[v.name,v.plate,v.person,v.category].join(' ').toLocaleLowerCase().includes(query.toLocaleLowerCase())))}
function stats(){let cards=[['car',state.vehicles.length,'Véhicules','dans le parc','sedan','',''],['users',state.vehicles.filter(v=>v.status==='Affecté').length,'Affectés','à des collaborateurs','grey-suv','green','Affecté'],['key',state.vehicles.filter(v=>v.status==='Disponible').length,'Disponibles',"prêts à l’attribution",'white-suv','','Disponible'],['tool',state.vehicles.filter(v=>v.status==='En entretien').length,'En entretien','actuellement','repair-compact','orange','En entretien']];return `<div class="stats">${cards.map(c=>`<button class="stat ${c[5]}" data-filter="${c[6]}"><div><span class="stat-icon">${icon(c[0])}</span><strong>${c[1]}</strong><h3>${c[2]}</h3><p>${c[3]}</p></div><img src="assets/${c[4]}.png" alt=""></button>`).join('')}</div>`}
function table(list,compact=false){return `<div class="table-wrap"><table><thead><tr><th>#</th><th>Véhicule</th><th>Immatriculation</th><th>Catégorie</th><th>Utilisateur</th><th>Statut</th><th>Kilométrage</th>${compact?'':'<th></th>'}</tr></thead><tbody>${list.map((v,i)=>`<tr data-detail="${esc(v.id)}" tabindex="0" aria-label="Ouvrir ${esc(v.name)}"><td>${i+1}</td><td><span class="vehicle-name">${photo(v)}${esc(v.name)}</span></td><td>${esc(v.plate)}</td><td>${esc(v.category)}</td><td>${esc(v.person||'—')}</td><td>${status(v.status)}</td><td class="km">${kmLabel(v.km)}</td>${compact?'':`<td><button class="text-button" data-edit="${esc(v.id)}">Modifier</button></td>`}</tr>`).join('')||'<tr><td colspan="8" class="empty">Aucun véhicule ne correspond à votre recherche.</td></tr>'}</tbody></table></div>`}
function dueRow(v,title,d){return `<div class="due-row" data-detail="${esc(v.id)}">${photo(v)}<div class="info"><strong>${esc(v.name)}</strong><small>${esc(v.plate)}</small>${title?`<small>${esc(title)}</small>`:''}</div><div class="due-date ${days(d)<0?'overdue':''}">▢ &nbsp;${date(d)}<small>${relative(d)}</small></div></div>`}
function upcoming(){return state.maintenance.filter(m=>!m.done&&vehicle(m.vehicle)).sort((a,b)=>a.date.localeCompare(b.date))}
function insurers(){return state.vehicles.filter(v=>v.insurance).sort((a,b)=>a.insurance.localeCompare(b.insurance))}
function duePanel(){const m=upcoming(),ins=insurers();return `<section class="panel"><div class="panel-title"><h2>Prochaines échéances</h2><a href="#deadlines" class="text-button">Voir toutes <span>→</span></a></div><div class="tabs"><button class="${dueTab==='maintenance'?'active':''}" data-tab="maintenance">Entretiens (${m.length})</button><button class="${dueTab==='insurance'?'active':''}" data-tab="insurance">Assurances (${ins.length})</button></div><div>${dueTab==='maintenance'?m.slice(0,3).map(x=>dueRow(vehicle(x.vehicle),x.title,x.date)).join('')||'<p class="empty">Aucun entretien prévu.</p>':ins.slice(0,3).map(v=>dueRow(v,'Assurance automobile',v.insurance)).join('')}</div><h3 class="sub-title">${dueTab==='maintenance'?"Échéances d’assurance":"Entretiens à venir"} (${dueTab==='maintenance'?ins.length:m.length})</h3>${dueTab==='maintenance'?ins.slice(0,3).map(v=>dueRow(v,'',v.insurance)).join(''):m.slice(0,3).map(x=>dueRow(vehicle(x.vehicle),x.title,x.date)).join('')}<div class="due-note">${icon('shield')}Consultez vos échéances pour anticiper les renouvellements et les interventions.</div></section>`}
function dashboard(){return head('Gestion du parc automobile',"Vue d’ensemble du parc, des affectations, des entretiens et des échéances.")+stats()+`<div class="dashboard-grid"><section class="panel"><div class="panel-title"><h2>Véhicules et affectations</h2><a href="#vehicles" class="text-button">Voir tous les véhicules <span>→</span></a></div>${table(filtered().slice(0,7),true)}<div class="table-bottom"><span>${Math.min(filtered().length,7)} sur ${filtered().length} véhicules</span><span>Données partagées</span></div></section>${duePanel()}</div>`}
function vehicles(){return head('Véhicules',"Retrouvez et gérez tous les véhicules de votre parc.",addButton('Ajouter un véhicule','vehicle'))+stats()+`<section class="panel"><div class="toolbar"><div class="filters"><select id="statusFilter" aria-label="Filtrer par statut"><option value="">Tous les statuts</option>${['Affecté','Disponible','En entretien','À vérifier','Accidenté / Immobilisé'].map(s=>`<option ${filter===s?'selected':''}>${s}</option>`).join('')}</select><span style="padding:10px;color:#8c98aa;font-size:11px">${filtered().length} véhicules</span></div><button class="secondary" data-export="vehicles">${icon('download')}Exporter CSV</button></div>${table(filtered())}</section>`}
function assignments(){let list=filtered().filter(v=>v.status==='Affecté');return head('Affectations','Attribuez un véhicule à un collaborateur et suivez les disponibilités.',addButton('Nouvelle affectation','assignment'))+`<section class="panel"><div class="panel-title"><h2>Véhicules affectés (${list.length})</h2></div>${table(list)}</section>`}
function maintenance(){return head('Entretiens','Planifiez les interventions et suivez les dépenses de maintenance.',addButton('Planifier un entretien','maintenance'))+`<section class="panel"><div class="panel-title"><h2>Programme d’entretien</h2><span class="sample">${upcoming().length} à réaliser</span></div><div class="table-wrap"><table><thead><tr><th>Véhicule</th><th>Intervention</th><th>Date</th><th>Coût (FCFA)</th><th>État</th><th>Action</th></tr></thead><tbody>${state.maintenance.filter(m=>vehicle(m.vehicle)).sort((a,b)=>a.date.localeCompare(b.date)).map(m=>`<tr><td><span class="vehicle-name">${photo(vehicle(m.vehicle))}${esc(vehicle(m.vehicle).name)}<br>${esc(vehicle(m.vehicle).plate)}</span></td><td>${esc(m.title)}</td><td>${date(m.date)}</td><td>${fmt(m.cost)}</td><td>${m.done?'Terminé':relative(m.date)}</td><td>${m.done?'✓':`<button class="text-button" data-complete="${m.id}">Marquer terminé</button>`}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Aucun entretien planifié.</td></tr>'}</tbody></table></div></section>`}
function reservations(){return head('Réservations','Organisez les déplacements et réservez les véhicules disponibles.',addButton('Nouvelle réservation','reservation'))+`<section class="panel"><div class="panel-title"><h2>Planning des réservations</h2></div><div class="table-wrap"><table><thead><tr><th>Véhicule</th><th>Utilisateur</th><th>Début</th><th>Fin</th><th>Motif</th><th>Action</th></tr></thead><tbody>${state.reservations.map(r=>`<tr><td>${esc(vehicle(r.vehicle)?.name||'Véhicule retiré')}<br>${esc(vehicle(r.vehicle)?.plate||'')}</td><td>${esc(r.person)}</td><td>${date(r.start)}</td><td>${date(r.end)}</td><td>${esc(r.reason)}</td><td><button class="text-button" data-cancel-res="${r.id}">Annuler</button></td></tr>`).join('')||`<tr><td colspan="6"><div class="empty">${icon('calendar')}<h3>Votre prochain déplacement commence ici</h3><p>Aucune réservation pour le moment.</p><button class="primary" style="margin-top:20px" data-add="reservation">Réserver un véhicule</button></div></td></tr>`}</tbody></table></div></section>`}
function deadlines(){return head('Échéances','Anticipez les entretiens et les renouvellements d’assurance.')+`<div class="report-grid"><section class="panel"><div class="panel-title"><h2>Entretiens à venir</h2><button class="text-button" data-add="maintenance">+ Planifier</button></div>${upcoming().map(m=>dueRow(vehicle(m.vehicle),m.title,m.date)).join('')||'<p class="empty">Aucun entretien prévu.</p>'}</section><section class="panel"><div class="panel-title"><h2>Assurances</h2></div>${insurers().map(v=>dueRow(v,'Assurance automobile',v.insurance)).join('')}</section></div>`}
function reports(){const total=state.vehicles.length,assigned=state.vehicles.filter(v=>v.status==='Affecté').length;return head('Rapports','Une vision claire de l’activité et de la composition de votre parc.',`<button class="secondary" data-export="vehicles">${icon('download')}Exporter le parc</button>`)+stats()+`<div class="report-grid"><section class="panel"><div class="panel-title"><h2>Répartition du parc</h2></div>${['Affecté','Disponible','En entretien','À vérifier','Accidenté / Immobilisé'].map((s,i)=>{const n=state.vehicles.filter(v=>v.status===s).length;return `<div class="bar-row"><span>${s}</span><div class="bar"><i style="width:${total?n/total*100:0}%;background:${['#34ae7b','#2783dc','#e6ad4d','#8b95a5','#dc5353'][i]}"></i></div><b>${n}</b></div>`}).join('')}<div class="metric">Taux d’affectation <b>${total?Math.round(assigned/total*100):0} %</b></div><div class="metric">Kilométrage connu (${state.vehicles.filter(v=>v.km!==null).length}/${total} véhicules) <b>${state.vehicles.some(v=>v.km!==null)?fmt(state.vehicles.reduce((a,v)=>a+(v.km??0),0))+' km':'Non renseigné'}</b></div></section><section class="panel"><div class="panel-title"><h2>Suivi des entretiens</h2></div><div class="metric">Interventions terminées <b>${state.maintenance.filter(m=>m.done).length}</b></div><div class="metric">Dépenses réalisées <b>${fmt(state.maintenance.filter(m=>m.done).reduce((a,m)=>a+Number(m.cost),0))} FCFA</b></div><div class="metric">Budget à prévoir <b>${fmt(state.maintenance.filter(m=>!m.done).reduce((a,m)=>a+Number(m.cost),0))} FCFA</b></div><div class="metric">Échéances en retard <b>${upcoming().filter(m=>days(m.date)<0).length+insurers().filter(v=>days(v.insurance)<0).length}</b></div></section></div>`}
function access(){return head('Accès utilisateurs','Votre espace AUTO ORYX et les possibilités de collaboration.')+`<div class="notice">Cette version fonctionne avec un espace personnel. Les données sont sauvegardées dans ce navigateur. La gestion de plusieurs comptes et la synchronisation entre appareils nécessitent une base de données partagée.</div><section class="panel"><div class="panel-title"><h2>Votre espace</h2><span class="sample">Propriétaire</span></div><div class="metric">Profil <b>Administrateur</b></div><div class="metric">Gestion des véhicules et des affectations <b>Activée</b></div><div class="metric">Planification et rapports <b>Activés</b></div><div class="metric">Sauvegarde des données <b>Export / restauration JSON</b></div><div class="metric">Stockage local <b>${storageOK?'Disponible':'Indisponible'}</b></div><p style="margin-top:20px;font-size:12px">Effectuez régulièrement une sauvegarde pour conserver vos modifications.</p><button class="primary" style="margin-top:16px" onclick="backup()">Sauvegarder mes données</button></section>`}
function render(){page=location.hash.slice(1)||'dashboard';if(!routes.some(r=>r[0]===page))page='dashboard';$('#nav').innerHTML=routes.map(r=>`<a href="#${r[0]}" class="${page===r[0]?'active':''}">${icon(r[2])}<span>${r[1]}</span></a>`).join('');$('#main').innerHTML=({dashboard,vehicles,assignments,reservations,maintenance,deadlines,reports,access,exits,accidents}[page])();$('#sidebar').classList.remove('open');}
window.addEventListener('hashchange',()=>{filter='';render()});$('#searchIcon').innerHTML=icon('search');$('#notifications').innerHTML=icon('bell');$('#notifications').onclick=()=>location.hash='deadlines';$('#search').oninput=e=>{query=e.target.value;render()};$('#menu').onclick=()=>$('#sidebar').classList.toggle('open');
const field=(label,name,type='text',value='',extra='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select=(label,name,options,value='')=>`<label class="field">${label}<select name="${name}" required>${options.map(o=>{let val=Array.isArray(o)?o[0]:o,label=Array.isArray(o)?o[1]:o;return `<option value="${esc(val)}" ${String(val)===String(value)?'selected':''}>${esc(label)}</option>`}).join('')}</select></label>`;
const vehicleOptions=(list=state.vehicles)=>list.map(v=>[v.id,`${v.name} · ${v.plate}`]);
let formType='',editId='';
function openForm(type,id=''){formType=type;editId=id;const v=vehicle(id);
 vehiclePhotoSession++;vehiclePhotoBusy=false;vehiclePhotoDraft=v?.photo||'';let html='',title='';if(type==='vehicle'){title=v?'Modifier le véhicule':'Ajouter un véhicule';html=field('Marque et modèle','name','text',v?.name||'','required maxlength="80" placeholder="Ex. Toyota Corolla"')+field('Immatriculation','plate','text',v?.plate||'','required maxlength="25" placeholder="Ex. AA-123-BF"')+select('Catégorie','category',['Non renseignée','Berline','SUV','Pick-up','Utilitaire','Autre'],v?.category)+select('Statut','status',['Disponible','Affecté','En entretien','À vérifier','Accidenté / Immobilisé'],v?.status)+field('Collaborateur (obligatoire si affecté)','person','text',v?.person||'','maxlength="80"')+field('Kilométrage','km','number',v?.km||0,'required min="0" step="1"')+field('Échéance de l’assurance','insurance','date',v?.insurance||'');}
if(type==='assignment'){title='Nouvelle affectation';const available=state.vehicles.filter(v=>v.status==='Disponible');if(!available.length)return toast('Aucun véhicule disponible.');html=select('Véhicule disponible','vehicle',vehicleOptions(available))+field('Nom du collaborateur','person','text','','required maxlength="80"');}
if(type==='maintenance'){title='Planifier un entretien';if(!state.vehicles.length)return toast('Ajoutez d’abord un véhicule.');html=select('Véhicule','vehicle',vehicleOptions())+field('Intervention','title','text','','required maxlength="100" placeholder="Ex. Vidange et filtres"')+field('Date prévue','date','date',today(),'required')+field('Coût prévu (FCFA)','cost','number',0,'required min="0" step="1"');}
if(type==='reservation'){title='Nouvelle réservation';const available=state.vehicles.filter(v=>v.status==='Disponible');if(!available.length)return toast('Aucun véhicule disponible.');html=select('Véhicule','vehicle',vehicleOptions(available))+field('Collaborateur','person','text','','required maxlength="80"')+field('Début','start','date',today(),'required')+field('Fin','end','date',today(),'required')+field('Motif du déplacement','reason','text','','required maxlength="120"');}
$('#modalTitle').textContent=title;$('#fields').innerHTML=html;$('#dialog').showModal();}
$('#close').onclick=$('#cancel').onclick=()=>$('#dialog').close();
$('#form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));for(const k of ['name','plate','person','title','reason']){if(k in data)data[k]=data[k].trim()}if((formType==='vehicle'&&(!data.name||!data.plate))||(formType==='assignment'&&!data.person)||(formType==='reservation'&&(!data.person||!data.reason))||(formType==='maintenance'&&!data.title))return toast('Complétez les champs obligatoires.');if(formType==='vehicle'){if(state.vehicles.some(v=>v.id!==editId&&v.plate.toUpperCase()===data.plate.trim().toUpperCase()))return toast('Cette immatriculation existe déjà.');if(data.status==='Affecté'&&!data.person.trim())return toast('Indiquez le collaborateur pour ce véhicule affecté.');const old=vehicle(editId);const rec={...data,name:data.name.trim(),plate:data.plate.trim().toUpperCase(),person:data.status==='Affecté'?data.person.trim():'',km:Number(data.km),id:editId||uid(),image:old?.image||(data.category==='Berline'?'sedan':'suv')};const previous=state;state=candidate;if(!save()){state=previous;return toast('La fiche n’a pas été enregistrée : stockage plein ou indisponible. Retirez la photo ou sauvegardez vos données.')}
  $('#dialog').close();render();return toast('Fiche et photo enregistrées dans la base partagée.');}
if(formType==='assignment'){const v=vehicle(data.vehicle);if(!v||v.status!=='Disponible')return toast('Ce véhicule n’est plus disponible.');v.status='Affecté';v.person=data.person.trim();}
if(formType==='maintenance')state.maintenance.push({...data,id:uid(),done:false,cost:Number(data.cost)});
if(formType==='reservation'){if(data.end<data.start)return toast('La fin doit être postérieure ou égale au début.');if(state.reservations.some(r=>r.vehicle===data.vehicle&&data.start<=r.end&&data.end>=r.start))return toast('Ce véhicule est déjà réservé sur cette période.');state.reservations.push({...data,id:uid()});}
save();$('#dialog').close();render();toast(storageOK?'Enregistrement en cours…':'Modification en mémoire : exportez une sauvegarde.');};
function details(id){const v=vehicle(id);if(!v)return;$('#modalTitle').textContent=v.name;$('#fields').innerHTML=`<img class="detail-photo" src="assets/${esc(v.image)}.png" alt=""><dl class="details-grid">${[['Immatriculation',v.plate],['Catégorie',v.category],['Collaborateur',v.person||'—'],['Statut',v.status],['Kilométrage',fmt(v.km)+' km'],['Assurance',date(v.insurance)]].map(([k,val])=>`<div><dt>${k}</dt><dd>${esc(val)}</dd></div>`).join('')}</dl><button type="button" class="primary" style="width:100%;margin-top:20px" id="detailEdit">Modifier ce véhicule</button>${v.status==='Affecté'?'<button type="button" class="secondary" style="width:100%;margin-top:10px" id="release">Terminer l’affectation</button>':''}`;$('#dialog').showModal();$('#dialog .modal-actions').style.display='none';$('#detailEdit').onclick=()=>{$('#dialog').close();openForm('vehicle',id)};if($('#release'))$('#release').onclick=()=>{v.status='Disponible';v.person='';save();$('#dialog').close();render();toast('Le véhicule est de nouveau disponible.')};}
$('#dialog').addEventListener('close',()=>{$('#dialog .modal-actions').style.display='flex'});
document.addEventListener('click',e=>{const add=e.target.closest('[data-add]'),edit=e.target.closest('[data-edit]'),detail=e.target.closest('[data-detail]'),filterBtn=e.target.closest('[data-filter]'),tab=e.target.closest('[data-tab]'),complete=e.target.closest('[data-complete]'),cancel=e.target.closest('[data-cancel-res]');if(add)openForm(add.dataset.add);else if(edit){e.stopPropagation();openForm('vehicle',edit.dataset.edit)}else if(detail)details(detail.dataset.detail);else if(filterBtn){const f=filterBtn.dataset.filter;if(page!=='vehicles'){location.hash='vehicles';setTimeout(()=>{filter=f;render()},0)}else{filter=f;render()}}else if(tab){dueTab=tab.dataset.tab;render()}else if(complete){const m=state.maintenance.find(m=>m.id===complete.dataset.complete);m.done=true;const v=vehicle(m.vehicle);if(v&&v.status==='En entretien'){v.status='Disponible';v.person=''}save();render();toast('Entretien terminé.')}else if(cancel){if(confirm('Annuler cette réservation ?')){state.reservations=state.reservations.filter(r=>r.id!==cancel.dataset.cancelRes);save();render();toast('Réservation annulée.')}}if(e.target.closest('[data-export]'))exportCSV();});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('tr[data-detail]')){e.preventDefault();details(e.target.dataset.detail)}});
document.addEventListener('change',e=>{if(e.target.id==='statusFilter'){filter=e.target.value;render()}});
function download(content,type,name){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportCSV(){const clean=v=>'"'+String(v??'').replace(/^[=+@\-]/,"'$&").replace(/"/g,'""')+'"';download('\ufeff'+[['Véhicule','Immatriculation','Catégorie','Collaborateur','Statut','Kilométrage','Assurance'],...filtered().map(v=>[v.name,v.plate,v.category,v.person,v.status,v.km,v.insurance])].map(r=>r.map(clean).join(';')).join('\r\n'),'text/csv;charset=utf-8',`AUTO_ORYX_Parc_${today()}.csv`);toast('Export du parc téléchargé.')}
function backup(){download(JSON.stringify(state,null,2),'application/json',`AUTO_ORYX_Sauvegarde_${today()}.json`);toast('Sauvegarde téléchargée.')}
$('#backup').onclick=backup;$('#restore').onclick=()=>$('#restoreFile').click();
$('#restoreFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;const data=JSON.parse(await f.text());const strings=(v,keys)=>keys.every(k=>typeof v[k]==='string');if(data.schema!==1||!Array.isArray(data.vehicles)||!Array.isArray(data.maintenance)||!Array.isArray(data.reservations))throw Error();if(!data.vehicles.every(v=>strings(v,['id','name','plate','category','person','status','image'])&&['Affecté','Disponible','En entretien'].includes(v.status)&&Number.isFinite(v.km)&&v.km>=0&&['sedan','suv','white-suv','grey-suv'].includes(v.image)&&(!v.insurance||/^\d{4}-\d{2}-\d{2}$/.test(v.insurance))))throw Error();if(new Set(data.vehicles.map(v=>v.id)).size!==data.vehicles.length)throw Error();if(!data.maintenance.every(m=>strings(m,['id','vehicle','title','date'])&&/^\d{4}-\d{2}-\d{2}$/.test(m.date)&&Number.isFinite(m.cost)&&m.cost>=0&&typeof m.done==='boolean'&&data.vehicles.some(v=>v.id===m.vehicle)))throw Error();if(!data.reservations.every(r=>strings(r,['id','vehicle','person','start','end','reason'])&&r.start<=r.end&&/^\d{4}-\d{2}-\d{2}$/.test(r.start)&&/^\d{4}-\d{2}-\d{2}$/.test(r.end)&&data.vehicles.some(v=>v.id===r.vehicle)))throw Error();if(!confirm('Remplacer les données de cet appareil par cette sauvegarde ? Exportez d’abord les données actuelles si vous souhaitez les conserver.'))return;state=data;save();render();toast('Sauvegarde restaurée.')}catch{toast('Fichier de sauvegarde invalide ou incompatible.')}finally{e.target.value=''}};

/* Version 2 : fiche complète et suivi des exigences du parc. */
const originalOpenForm=openForm;
const originalSubmit=$('#form').onsubmit;
const originalVehicles=vehicles;
const originalMaintenance=maintenance;
const originalReports=reports;
const showValue=v=>v===null||v===undefined||v===''?'Non renseigné':esc(v);
const numberValue=v=>v===null||v===undefined?'Non renseigné':fmt(v);
const section=(title,content)=>`<fieldset class="form-section"><legend>${title}</legend><div class="form-grid">${content}</div></fieldset>`;
const requiredText='required maxlength="100"';
const integerInput='min="0" step="1"';
const groupNote=t=>`<p class="field-note">${t}</p>`;
let vehiclePhotoDraft='',vehiclePhotoBusy=false,vehiclePhotoSession=0;
const frequency=v=>[v.serviceIntervalKm!==null?`${fmt(v.serviceIntervalKm)} km`:'',v.serviceIntervalMonths!==null?`${v.serviceIntervalMonths} mois`:''].filter(Boolean).join(' / ')||'Non renseignée';
filtered=()=>state.vehicles.filter(v=>(!filter||v.status===filter)&&(!query||[v.name,v.brand,v.model,v.plate,v.person,v.userName,v.usedBy,v.entity,v.department,v.purchasedBy,v.category,v.fuel,v.color].join(' ').toLocaleLowerCase().includes(query.toLocaleLowerCase())));
openForm=function(type,id=''){
 if(type!=='vehicle'&&type!=='assignment'){originalOpenForm(type,id);$('#dialog').classList.remove('wide');$('#dialog .modal-actions').style.display='flex';return;}
 formType=type;editId=id;const v=vehicle(id);
 vehiclePhotoSession++;vehiclePhotoBusy=false;vehiclePhotoDraft=v?.photo||'';
 $('#dialog .modal-actions').style.display='flex';$('#dialog').classList.toggle('wide',type==='vehicle');
 let html='';
 if(type==='vehicle'){
  html=vehiclePhotoFields()+section('1 · Identification du véhicule',
   field('Marque *','brand','text',v?.brand||'',requiredText+' placeholder="Ex. Toyota"')+
   field('Modèle *','model','text',v?.model||'',requiredText+' placeholder="Ex. Corolla"')+
   field('Carburant','fuel','text',v?.fuel||'','maxlength="100" placeholder="Ex. GASOIL, ESSENCE, SUPER"')+
   field('Couleur','color','text',v?.color||'','maxlength="100"')+
   field('Immatriculation *','plate','text',v?.plate||'','required maxlength="25"')+
   select('Catégorie','category',['Non renseignée','Berline','SUV','Pick-up','Utilitaire','Autre'],v?.category)+
   field('Date de mise en circulation','firstRegistration','date',v?.firstRegistration||'')+
   field('Année de fabrication (si connue)','year','number',v?.year??'',`min="1900" max="${new Date().getFullYear()+1}" step="1"`))+
  section('2 · Organisation et utilisateur',
   field('ENTITÉ','entity','text',v?.entity||'','maxlength="100" placeholder="Société, filiale ou site"')+
   field('Acheté par','purchasedBy','text',v?.purchasedBy||'','maxlength="100" placeholder="Personne ou société ayant acheté le véhicule"')+
   field('Utilisé par','usedBy','text',v?.usedBy||'','maxlength="100" placeholder="Service ou personne utilisatrice"')+
   field('Département','department','text',v?.department||'','maxlength="100"')+
   field('Nom de l’utilisateur','userName','text',v?.userName||'','maxlength="100"')+
   select('Statut','status',['Disponible','Affecté','En entretien','À vérifier','Accidenté / Immobilisé'],v?.status))+
  section('3 · Kilométrage et entretien',
   field('Kilométrage actuel','km','number',v?.km??'',integerInput+' placeholder="Laisser vide si inconnu"')+
   field('Prochaine vidange — kilométrage cible (km)','nextOilKm','number',v?.nextOilKm??'',integerInput)+
   field('Prochaine vidange — date cible','nextOilDate','date',v?.nextOilDate||'')+
   field('Fréquence d’entretien — tous les (km)','serviceIntervalKm','number',v?.serviceIntervalKm??'','min="1" step="1"')+
   field('Fréquence d’entretien — tous les (mois)','serviceIntervalMonths','number',v?.serviceIntervalMonths??'','min="1" step="1"'))+
  groupNote('Renseignez la prochaine vidange en date et/ou en kilomètres selon le carnet d’entretien. La fréquence est une référence ; elle ne décale pas automatiquement les échéances.')+
  section('4 · Visites techniques et assurance',
   field('Date de la visite technique','lastInspection','date',v?.lastInspection||'')+
   field('Date de la prochaine visite technique','nextInspection','date',v?.nextInspection||'')+
   field('Échéance de l’assurance','insurance','date',v?.insurance||''))+
  groupNote('* Champs obligatoires. Pour un véhicule affecté, renseignez le nom de l’utilisateur. Les autres champs restent vides tant que les informations ne sont pas disponibles.');
 }else{
  const available=state.vehicles.filter(v=>v.status==='Disponible');if(!available.length)return toast('Aucun véhicule disponible.');
  html=select('Véhicule disponible','vehicle',vehicleOptions(available))+field('Nom de l’utilisateur *','userName','text','',requiredText)+field('Utilisé par','usedBy','text','','maxlength="100"')+field('Département','department','text','','maxlength="100"');
 }
 $('#modalTitle').textContent=type==='vehicle'?(v?'Modifier la fiche véhicule':'Ajouter un véhicule'):'Nouvelle affectation';
 $('#fields').innerHTML=html;$('#dialog').showModal();
 if(type==='vehicle')bindVehiclePhoto();
};
$('#form').onsubmit=function(e){
 if(formType!=='vehicle'&&formType!=='assignment')return originalSubmit.call(this,e);
 e.preventDefault();if(vehiclePhotoBusy)return toast('Patientez pendant la préparation de la photo.');const data=Object.fromEntries(new FormData(this));for(const k in data)data[k]=data[k].trim();
 if(formType==='assignment'){
  if(!data.userName)return toast('Renseignez le nom de l’utilisateur.');
  const v=vehicle(data.vehicle);if(!v||v.status!=='Disponible')return toast('Ce véhicule n’est plus disponible.');
  Object.assign(v,{status:'Affecté',userName:data.userName,person:data.userName,usedBy:data.usedBy,department:data.department});
 }else{
  if(!data.brand||!data.model||!data.plate)return toast('Renseignez la marque, le modèle et l’immatriculation.');
  if(state.exitedVehicles.some(e=>!e.cancelledAt&&Fleet.plateKey(e.vehicle.plate)===Fleet.plateKey(data.plate)))return toast('Cette immatriculation est déjà sortie du parc. Consultez Sorties du parc.');
  if(state.vehicles.some(v=>v.id!==editId&&Fleet.plateKey(v.plate)===Fleet.plateKey(data.plate)))return toast('Cette immatriculation existe déjà.');
  if(data.status==='Affecté'&&!data.userName)return toast('Renseignez le nom de l’utilisateur pour ce véhicule affecté.');
  for(const k of Fleet.numberKeys)data[k]=data[k]===''?null:Number(data[k]);
  data.km=data.km===''?null:Number(data.km);
  if(state.accidents.some(a=>!a.closedAt&&a.vehicle.id===editId)&&data.status!=='Accidenté / Immobilisé')return toast('Clôturez le sinistre pour remettre ce véhicule en service.');
  const old=vehicle(editId),rec={...old,...data,id:editId||uid(),name:`${data.brand} ${data.model}`.trim(),plate:data.plate.toUpperCase(),person:data.userName,photo:vehiclePhotoDraft,image:old?.image||(data.category==='Berline'?'sedan':'suv')};
  const candidate={...state,vehicles:old?state.vehicles.map(v=>v.id===editId?rec:v):[...state.vehicles,rec]};
  try{Fleet.validate(candidate)}catch{return toast('Vérifiez les nombres et les dates : la prochaine visite ne doit pas précéder la dernière.')}
  const previous=state;state=candidate;if(!save()){state=previous;return toast('La fiche n’a pas été enregistrée : stockage plein ou indisponible. Retirez la photo ou sauvegardez vos données.')}
  $('#dialog').close();render();return toast('Fiche et photo enregistrées dans la base partagée.');
 }
 save();$('#dialog').close();render();toast(storageOK?'Enregistrement en cours…':'Modification en mémoire : exportez une sauvegarde.');
};
const detailRows=v=>[
 ['Marque',v.brand],['Modèle',v.model],['Carburant',v.fuel],['Couleur',v.color],['Immatriculation',v.plate],['Catégorie',v.category],
 ['ENTITÉ',v.entity],['Acheté par',v.purchasedBy],['Utilisé par',v.usedBy],['Département',v.department],['Nom de l’utilisateur',v.userName],['Statut',v.status],
 ['Date de mise en circulation',v.firstRegistration?date(v.firstRegistration):''],['Année de fabrication',v.year],['Âge depuis la mise en circulation',vehicleAge(v.firstRegistration)],
 ['Kilométrage actuel',`${kmLabel(v.km)}`],['Prochaine vidange — kilomètres',v.nextOilKm!==null?`${fmt(v.nextOilKm)} km`:''],['Prochaine vidange — date',v.nextOilDate?date(v.nextOilDate):''],['Fréquence d’entretien',frequency(v)],
 ['Date de la visite technique',v.lastInspection?date(v.lastInspection):''],['Prochaine visite technique',v.nextInspection?date(v.nextInspection):''],['Échéance de l’assurance',v.insurance?date(v.insurance):'']
];
details=function(id){
 const v=vehicle(id);if(!v)return;formType='detail';$('#dialog').classList.add('wide');$('#modalTitle').textContent=v.name;
 $('#fields').innerHTML=`<div class="detail-header">${photo(v)}<div><strong>${esc(v.plate)}</strong><p>${esc(v.entity||'Entité non renseignée')}</p></div>${status(v.status)}</div><dl class="details-grid">${detailRows(v).map(([k,val])=>`<div><dt>${k}</dt><dd>${showValue(val)}</dd></div>`).join('')}</dl><div class="detail-buttons"><button type="button" class="primary" id="detailEdit">Modifier la fiche</button><button type="button" class="secondary" id="printVehicle">Imprimer la fiche</button>${v.status==='Affecté'?'<button type="button" class="secondary" id="release">Terminer l’affectation</button>':''}</div>`;
 $('#dialog .modal-actions').style.display='none';$('#dialog').showModal();
 $('#detailEdit').onclick=()=>{$('#dialog').close();openForm('vehicle',id)};
 $('#printVehicle').onclick=()=>window.print();
 if($('#release'))$('#release').onclick=()=>{v.status='Disponible';v.person='';v.userName='';v.usedBy='';save();$('#dialog').close();render();toast('Affectation terminée. Le véhicule est disponible.')};
};
function alertCard(a){const v=vehicle(a.vehicle);return `<button class="service-alert ${a.level}" data-detail="${esc(v.id)}"><div class="service-alert-icon">${icon(a.type==='oil'?'tool':'calendar')}</div><div class="info"><strong>${esc(v.name)} · ${esc(v.plate)}</strong><small>${a.label}</small><small>${a.date?`${date(a.date)} · ${relative(a.date)}`:''}${a.date&&a.km!==undefined&&a.km!==null?' • ':''}${a.km!==undefined&&a.km!==null?`${fmt(a.km)} km · ${a.remainingKm===null?'kilométrage actuel à renseigner':a.remainingKm<=0?'seuil atteint':fmt(a.remainingKm)+' km restants'}`:''}</small></div><span class="alert-badge">${a.level==='late'?'À traiter':a.level==='soon'?'À prévoir':'Planifié'}</span></button>`}
function services(){return Fleet.serviceAlerts(state.vehicles,today())}
function servicePanel(type,title){const list=services().filter(a=>a.type===type);return `<section class="panel"><div class="panel-title"><h2>${title}</h2><span class="sample">${list.length} renseignés</span></div>${list.map(alertCard).join('')||'<div class="empty"><p>Aucune échéance renseignée.</p><p>Complétez les fiches des véhicules pour activer ce suivi.</p></div>'}</section>`}
const oldDuePanel=duePanel;
duePanel=function(){const alerts=services().filter(a=>a.level!=='normal');return `<div class="right-panels">${alerts.length?`<section class="panel"><div class="panel-title"><h2>Vidanges et visites techniques</h2><a class="text-button" href="#deadlines">Voir toutes →</a></div>${alerts.slice(0,3).map(alertCard).join('')}</section>`:''}${oldDuePanel()}</div>`};
const oldDeadlines=deadlines;
deadlines=function(){return head('Échéances','Suivez les vidanges, les visites techniques, les entretiens et les assurances.')+`<div class="notice">Les alertes apparaissent 30 jours avant une échéance ou à 1 000 km de la prochaine vidange. Un seuil kilométrique atteint est signalé « À traiter ». Consultez le site pour voir les alertes ; aucun e-mail n’est envoyé.</div><div class="report-grid">${servicePanel('oil','Prochaines vidanges')}${servicePanel('inspection','Visites techniques')}</div><div class="section-gap"></div>`+oldDeadlines().replace(/^.*?<div class="report-grid">/s,'<div class="report-grid">')};
let fleetView='summary';
function completeTable(){const columns=[['brand','Marque'],['model','Modèle'],['plate','Immatriculation'],['fuel','Carburant'],['color','Couleur'],['entity','ENTITÉ'],['purchasedBy','Acheté par'],['usedBy','Utilisé par'],['firstRegistration','Mise en circulation'],['year','Année'],['department','Département'],['userName','Nom de l’utilisateur'],['km','Kilométrage actuel'],['nextOilKm','Vidange à (km)'],['nextOilDate','Vidange le'],['serviceIntervalKm','Fréquence (km)'],['serviceIntervalMonths','Fréquence (mois)'],['lastInspection','Dernière visite technique'],['nextInspection','Prochaine visite technique']];
 return `<div class="table-wrap complete-table"><table><thead><tr>${columns.map(c=>`<th>${c[1]}</th>`).join('')}<th>Action</th></tr></thead><tbody>${filtered().map(v=>`<tr data-detail="${esc(v.id)}" tabindex="0" aria-label="Ouvrir ${esc(v.name)}">${columns.map(([key])=>`<td>${Fleet.dateKeys.includes(key)?v[key]?date(v[key]):'—':key==='year'?esc(v[key]??'—'):typeof v[key]==='number'?fmt(v[key]):esc(v[key]||'—')}</td>`).join('')}<td><button class="text-button" data-edit="${esc(v.id)}">Modifier</button></td></tr>`).join('')||'<tr><td colspan="20" class="empty">Aucun véhicule.</td></tr>'}</tbody></table></div>`;
}
vehicles=function(){let html=originalVehicles();const toolbar=`<div class="view-switch" aria-label="Affichage des véhicules"><button data-view="summary" class="${fleetView==='summary'?'active':''}">Vue synthèse</button><button data-view="complete" class="${fleetView==='complete'?'active':''}">Tous les champs</button></div>`;html=html.replace('<section class="panel">',toolbar+'<section class="panel">');if(fleetView==='complete'){const start=html.indexOf('<div class="table-wrap">');html=html.slice(0,start)+completeTable()+'</section>'}return html;};
maintenance=function(){return originalMaintenance()+`<div class="section-gap"></div><div class="report-grid">${servicePanel('oil','Suivi des vidanges')}${servicePanel('inspection','Suivi des visites techniques')}</div>`};
reports=function(){return originalReports()+`<div class="section-gap"></div><section class="panel"><div class="panel-title"><h2>Suivi des vidanges et visites techniques</h2></div><div class="metric">Échéances à traiter <b>${services().filter(a=>a.level==='late').length}</b></div><div class="metric">Échéances à prévoir <b>${services().filter(a=>a.level==='soon').length}</b></div><p style="font-size:12px;margin-top:15px">Seules les dates et les cibles kilométriques renseignées sont comptabilisées.</p></section>`};
const exportColumns=[['brand','Marque'],['model','Modèle'],['plate','Immatriculation'],['fuel','Carburant'],['color','Couleur'],['entity','ENTITÉ'],['purchasedBy','Acheté par'],['usedBy','Utilisé par'],['firstRegistration','Date de mise en circulation'],['year','Année de fabrication'],['department','Département'],['userName','Nom de l’utilisateur'],['km','Kilométrage actuel'],['nextOilKm','Prochaine vidange (km)'],['nextOilDate','Prochaine vidange (date)'],['serviceIntervalKm','Fréquence entretien (km)'],['serviceIntervalMonths','Fréquence entretien (mois)'],['lastInspection','Date de la visite technique'],['nextInspection','Date de la prochaine visite technique'],['status','Statut'],['category','Catégorie'],['insurance','Échéance assurance']];
exportCSV=function(){const clean=v=>'"'+String(v??'').replace(/^[\s]*[=+@\-]/,"'$&").replace(/"/g,'""')+'"';download('\ufeff'+[exportColumns.map(c=>c[1]),...filtered().map(v=>exportColumns.map(c=>v[c[0]]))].map(row=>row.map(clean).join(';')).join('\r\n'),'text/csv;charset=utf-8',`AUTO_ORYX_Parc_Complet_${today()}.csv`);toast('Export complet téléchargé.');};
$('#restoreFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;const raw=JSON.parse(await f.text()),data=Fleet.validate(raw);if(!confirm('Remplacer les données de cet appareil par cette sauvegarde ? Sauvegardez les données actuelles avant de continuer.'))return;state=data;loadError=false;save();render();toast('Sauvegarde restaurée et mise au format V2.')}catch{toast('Fichier de sauvegarde invalide ou incompatible.')}finally{e.target.value=''}};
document.addEventListener('click',e=>{const view=e.target.closest('[data-view]');if(view){fleetView=view.dataset.view;render()}});
// Keep derived assignment fields consistent after the original completion action.
document.addEventListener('click',e=>{const btn=e.target.closest('[data-complete]');if(btn){const m=state.maintenance.find(m=>m.id===btn.dataset.complete),v=m&&vehicle(m.vehicle);if(v&&v.status==='Disponible'&&!v.person){v.userName='';v.usedBy='';save()}}});
const inheritedRender=render;
render=function(){inheritedRender();if(loadError){$('#main').insertAdjacentHTML('afterbegin','<div class="notice">Les données précédentes n’ont pas pu être lues. Elles n’ont pas été écrasées. Sauvegardez-les avant toute restauration.</div>')}$('#sidebar .sidebar-bottom small').textContent='Version 3 · Parc partagé';};
backup=function(){if(loadError){try{const raw=localStorage.getItem('auto-oryx-v1');if(raw)download(raw,'application/json',`AUTO_ORYX_Donnees_Originales_${today()}.json`)}catch{toast('Export indisponible.')}return}download(JSON.stringify(state,null,2),'application/json',`AUTO_ORYX_Sauvegarde_V2_${today()}.json`);toast('Sauvegarde complète téléchargée.');};
$('#backup').onclick=backup;

const baseToast=toast;
toast=function(t){if($('#dialog').open){let m=$('#formMessage');if(!m){m=document.createElement('div');m.id='formMessage';m.className='form-message';m.setAttribute('role','alert');$('#fields').prepend(m)}m.textContent=t;m.scrollIntoView({block:'nearest'})}baseToast(t)};

/* Photos personnelles : compression locale, aucune transmission au dépôt GitHub. */
function vehiclePhotoFields(){return `<fieldset class="form-section photo-section"><legend>Photo du véhicule</legend><div class="photo-editor"><img id="vehiclePhotoPreview" alt="Aperçu de la photo du véhicule" ${vehiclePhotoDraft?`src="${esc(vehiclePhotoDraft)}"`:'hidden'}><div><label class="secondary photo-picker">Choisir une photo<input id="vehiclePhotoFile" type="file" accept="image/jpeg,image/png,image/webp,image/heic,image/heif"></label><label class="secondary photo-picker">Prendre une photo<input id="vehiclePhotoCamera" type="file" accept="image/*" capture="environment"></label><button type="button" class="text-button" id="removeVehiclePhoto" ${vehiclePhotoDraft?'':'hidden'}>Retirer la photo</button><p id="vehiclePhotoStatus" role="status">${vehiclePhotoDraft?'Photo enregistrée.':'Aucune photo personnelle.'}</p><p class="field-note">Photo facultative, réduite automatiquement. Enregistrée dans Supabase après validation et incluse dans vos sauvegardes JSON. Sans photo, l’illustration reste affichée.</p></div></div></fieldset>`}
async function compactVehiclePhoto(file){
 if(!file||file.size>20*1024*1024)throw Error('Choisissez une image de moins de 20 Mo.');
 if(file.type==='image/svg+xml'||(file.type&&!file.type.startsWith('image/')))throw Error('Choisissez une photo JPEG, PNG ou WebP.');
 const url=URL.createObjectURL(file);
 try{
  const img=await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(Error('Image illisible. Essayez une photo JPEG, PNG ou WebP.'));im.src=url;});
  if(!img.naturalWidth||!img.naturalHeight)throw Error('Image illisible.');
  const canvas=document.createElement('canvas');
  for(const limit of [640,480,320]){
   const scale=Math.min(1,limit/Math.max(img.naturalWidth,img.naturalHeight));
   canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));
   const ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);
   for(const quality of [.78,.6,.42]){const data=canvas.toDataURL('image/jpeg',quality);if(data.length<=65000)return data;}
  }
  throw Error('Cette photo reste trop volumineuse. Essayez une autre image.');
 }finally{URL.revokeObjectURL(url)}
}
function bindVehiclePhoto(){
 const session=vehiclePhotoSession;let selection=0;
 const show=message=>{const img=$('#vehiclePhotoPreview');if(!img)return;img.hidden=!vehiclePhotoDraft;if(vehiclePhotoDraft)img.src=vehiclePhotoDraft;else img.removeAttribute('src');$('#removeVehiclePhoto').hidden=!vehiclePhotoDraft;$('#vehiclePhotoStatus').textContent=message;};
 const choose=async e=>{
  const file=e.target.files[0];if(!file)return;
  const token=++selection;vehiclePhotoBusy=true;$('#vehiclePhotoStatus').textContent='Préparation de la photo…';
  try{const data=await compactVehiclePhoto(file);if(session!==vehiclePhotoSession||token!==selection)return;vehiclePhotoDraft=data;show('Photo prête. Cliquez sur Enregistrer pour la conserver.');}
  catch(error){if(session===vehiclePhotoSession&&token===selection)show(error.message);}
  finally{if(session===vehiclePhotoSession&&token===selection)vehiclePhotoBusy=false;e.target.value='';}
 };
 $('#vehiclePhotoFile').onchange=choose;$('#vehiclePhotoCamera').onchange=choose;
 $('#removeVehiclePhoto').onclick=()=>{selection++;vehiclePhotoBusy=false;vehiclePhotoDraft='';show('Photo retirée. Cliquez sur Enregistrer pour confirmer.');};
}

/* Import de données personnelles par fichier local, avec aperçu et fusion par plaque. */
let pendingFleetImport=null;
const fleetImportInput=document.createElement('input');fleetImportInput.type='file';fleetImportInput.accept='.json,application/json';fleetImportInput.hidden=true;fleetImportInput.id='fleetImportFile';document.body.append(fleetImportInput);
const renderBeforeImport=render;
render=function(){renderBeforeImport();if(page==='vehicles'){const add=$('[data-add="vehicle"]');if(add){const button=document.createElement('button');button.className='secondary';button.id='openFleetImport';button.textContent='Importer des véhicules';button.onclick=()=>fleetImportInput.click();add.parentElement.append(button);}}
 if(['dashboard','vehicles','reports'].includes(page)){const missing=state.vehicles.filter(v=>v.status==='À vérifier').length;if(missing){const n=document.createElement('div');n.className='notice';n.textContent=missing+' véhicule(s) avec un statut à vérifier. Ils sont inclus dans le parc total, sans être comptés comme disponibles, affectés ou en entretien.';$('#main').insertBefore(n,$('#main').children[1]||null);}}
};
fleetImportInput.onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(loadError)throw Error('Exportez et restaurez d’abord les données illisibles avant tout import.');if(file.size>10*1024*1024)throw Error('Le fichier d’import est trop volumineux.');pendingFleetImport=Fleet.planImport(JSON.parse(await file.text()),state);
 const plan=pendingFleetImport;formType='fleet-import';vehiclePhotoSession++;vehiclePhotoBusy=false;$('#dialog').classList.add('wide');$('#modalTitle').textContent='Vérifier l’import des véhicules';$('#dialog .modal-actions').style.display='flex';$('#form button[type="submit"]').textContent='Confirmer l’import';
 $('#fields').innerHTML=`<div class="notice"><b>${plan.added} à ajouter · ${plan.updated} à mettre à jour · ${plan.unchanged} inchangé(s)</b><br>Aucun véhicule existant n’est supprimé. Pour une plaque déjà présente, les informations de cette feuille remplacent les champs d’identification affichés ci-dessous. Photos, kilométrages, statuts, catégories, entités, entretiens et réservations existants sont conservés.</div><p class="import-help">Les nouveaux véhicules ont un statut « À vérifier ». Kilométrage, année de fabrication, catégorie, ENTITÉ et échéances restent non renseignés. L’âge sera calculé depuis la mise en circulation. Sauvegardez vos données avant de confirmer.</p><button type="button" class="secondary" id="importBackup">Sauvegarder mes données actuelles</button><div class="table-wrap import-preview"><table><thead><tr><th>Action</th><th>Immatriculation</th><th>Marque / modèle</th><th>Carburant</th><th>Couleur</th><th>Acheté par</th><th>Utilisé par</th><th>Mise en circulation</th><th>Département</th><th>Utilisateur</th></tr></thead><tbody>${plan.items.map(i=>{const v=i.record;return `<tr><td>${i.action==='add'?'Ajouter':i.action==='update'?'Mettre à jour':'Inchangé'}</td><td>${esc(v.plate)}</td><td>${esc(v.name)}</td><td>${esc(v.fuel)}</td><td>${esc(v.color)}</td><td>${esc(v.purchasedBy)}</td><td>${esc(v.usedBy)}</td><td>${date(v.firstRegistration)}</td><td>${esc(v.department)}</td><td>${esc(v.userName)}</td></tr>`}).join('')}</tbody></table></div><p class="import-help">Ce fichier est lu sur cet appareil. Il ne doit pas être envoyé dans le dépôt GitHub public.</p>`;
 $('#importBackup').onclick=backup;$('#dialog').showModal();
 }catch(error){pendingFleetImport=null;toast(error.message==='Unexpected end of JSON input'?'Fichier JSON incomplet.':error.message||'Fichier d’import invalide.');}finally{e.target.value='';}};
const submitBeforeImport=$('#form').onsubmit;
$('#form').onsubmit=function(e){if(formType!=='fleet-import')return submitBeforeImport.call(this,e);e.preventDefault();if(!pendingFleetImport)return;const plan=pendingFleetImport,previous=state;state=plan.candidate;if(!save()){state=previous;return toast('Import non enregistré : stockage indisponible. Les données précédentes sont conservées.')}pendingFleetImport=null;$('#dialog').close();render();toast(plan.added+' véhicule(s) ajouté(s), '+plan.updated+' mis à jour.');};
const openFormBeforeImport=openForm;openForm=function(...args){$('#form button[type="submit"]').textContent='Enregistrer';pendingFleetImport=null;return openFormBeforeImport(...args)};

/* Suppression réversible : corbeille incluse dans les sauvegardes JSON. */
function applyFleetChange(candidate){const previous=state;state=candidate;if(save())return true;state=previous;toast('Changement non enregistré. Les données précédentes sont conservées.');return false;}
function removeVehicleToTrash(id){
 const v=vehicle(id);if(!v)return;
 const n=state.maintenance.filter(m=>m.vehicle===id).length,r=state.reservations.filter(x=>x.vehicle===id).length;
 if(!confirm('Supprimer '+v.name+' — '+v.plate+' du parc actif ?\n\nLa fiche enregistrée, sa photo, '+n+' entretien(s) et '+r+' réservation(s) seront déplacés dans la corbeille. Vous pourrez tout restaurer. Les changements non enregistrés du formulaire seront ignorés.'))return;
 try{if(!applyFleetChange(Fleet.archiveVehicle(state,id)))return;vehiclePhotoSession++;vehiclePhotoBusy=false;$('#dialog').close();render();toast('Véhicule déplacé dans la corbeille.');}catch(error){toast(error.message)}
}
function openFleetTrash(){
 formType='trash';vehiclePhotoSession++;vehiclePhotoBusy=false;$('#modalTitle').textContent='Corbeille des véhicules';$('#dialog').classList.add('wide');$('#dialog .modal-actions').style.display='none';
 const items=state.deletedVehicles||[];
 $('#fields').innerHTML='<p class="import-help">Ces véhicules ne sont plus dans le parc actif. Leur photo et leur historique sont conservés. La corbeille est incluse dans vos sauvegardes JSON.</p><div class="table-wrap"><table><thead><tr><th>Véhicule</th><th>Immatriculation</th><th>Historique conservé</th><th>Action</th></tr></thead><tbody>'+items.map(item=>`<tr><td>${esc(item.vehicle.name)}</td><td>${esc(item.vehicle.plate)}</td><td>${item.maintenance.length} entretien(s), ${item.reservations.length} réservation(s)</td><td><button type="button" class="secondary" data-restore-vehicle="${esc(item.id)}">Restaurer</button></td></tr>`).join('')+(items.length?'':'<tr><td colspan="4" class="empty">La corbeille est vide.</td></tr>')+'</tbody></table></div>';
 $('#dialog').showModal();
 if(items.length){
  const counts={vehicles:items.length,maintenance:items.reduce((n,e)=>n+e.maintenance.length,0),reservations:items.reduce((n,e)=>n+e.reservations.length,0),photos:items.filter(e=>e.vehicle.photo).length};
  $('#fields').insertAdjacentHTML('beforeend',`<section class="purge-section"><h3>Vider la corbeille</h3><p>Effacement définitif de <strong>${counts.vehicles} véhicule(s), ${counts.photos} photo(s), ${counts.maintenance} entretien(s) et ${counts.reservations} réservation(s)</strong> de la corbeille. Les véhicules du parc actif restent conservés.</p><p>Pour pouvoir récupérer ces fiches plus tard, téléchargez une sauvegarde avant de continuer.</p><button type="button" class="secondary" id="backupBeforeEmpty">Sauvegarder mes données</button><label class="field" for="emptyTrashWord">Écrivez VIDER pour activer le bouton<input id="emptyTrashWord" type="text" autocomplete="off" spellcheck="false" maxlength="5" placeholder="VIDER"></label><button type="button" class="danger-button" id="emptyFleetTrash" disabled>Vider définitivement la corbeille</button><p>Cette opération ne supprime pas les sauvegardes déjà téléchargées.</p></section>`);
  $('#backupBeforeEmpty').onclick=backup;
  $('#emptyTrashWord').onkeydown=e=>{if(e.key==='Enter')e.preventDefault()};
  $('#emptyTrashWord').oninput=e=>{$('#emptyFleetTrash').disabled=e.target.value!=='VIDER'};
  $('#emptyFleetTrash').onclick=()=>{
   if($('#emptyTrashWord').value!=='VIDER')return;
   if(!confirm('Vider définitivement la corbeille ?\n\n'+counts.vehicles+' véhicule(s), '+counts.photos+' photo(s), '+counts.maintenance+' entretien(s) et '+counts.reservations+' réservation(s) seront effacés. Cette action ne peut pas être annulée depuis la corbeille. Une sauvegarde antérieure sera nécessaire pour les récupérer.'))return;
   try{if(!applyFleetChange(Fleet.emptyTrash(state)))return;$('#dialog').close();render();openFleetTrash();toast('Corbeille vidée. Les véhicules du parc actif sont conservés.');}catch(error){toast(error.message)}
  };
 }
 $('#fields').querySelectorAll('[data-restore-vehicle]').forEach(button=>button.onclick=()=>{try{if(!applyFleetChange(Fleet.restoreVehicle(state,button.dataset.restoreVehicle)))return;$('#dialog').close();render();toast('Véhicule, photo et historique restaurés.');}catch(error){toast(error.message)}});
}
const formBeforeTrash=openForm;
openForm=function(type,id=''){formBeforeTrash(type,id);if(type==='vehicle'&&id&&vehicle(id)&&$('#dialog').open){const button=document.createElement('button');button.type='button';button.className='danger-button';button.id='deleteVehicle';button.textContent='Supprimer ce véhicule';button.onclick=()=>removeVehicleToTrash(id);$('#fields').append(button);}};
const renderBeforeTrash=render;
render=function(){renderBeforeTrash();if(page==='vehicles'){const add=$('[data-add="vehicle"]');if(add){const button=document.createElement('button');button.type='button';button.className='secondary';button.id='openFleetTrash';button.textContent='Corbeille ('+(state.deletedVehicles||[]).length+')';button.onclick=openFleetTrash;add.parentElement.append(button);}}};

/* Sorties du parc : dossiers séparés du parc actif et de la corbeille. */
let exitDocumentDraft=null,exitDocumentBusy=false,exitFormSession=0,pendingExitVehicle='',pendingCancelExit='';
function exitMoney(value){return value===null?'Non renseigné':fmt(value)+' FCFA'}
function exits(){
 const all=state.exitedVehicles||[],active=all.filter(e=>!e.cancelledAt),list=all.filter(e=>(exitTab==='active'?!e.cancelledAt:!!e.cancelledAt)&&(!query||[e.vehicle.name,e.vehicle.plate,e.reason,e.beneficiary,e.reference].join(' ').toLocaleLowerCase().includes(query.toLocaleLowerCase())));
 const sales=active.filter(e=>e.reason==='Vente / cession'),known=sales.filter(e=>e.amount!==null);
 return head('Sorties du parc','Ventes, cessions, mises au rebut, restitutions et transferts hors parc.',`<div class="exit-actions"><button class="secondary" data-exit-export>Exporter les sorties CSV</button><button class="primary" data-new-exit>Enregistrer une sortie</button></div>`)+`<section class="panel"><div class="exit-summary"><span><b>${active.length}</b> véhicule(s) sorti(s)</span><span>Montants de vente / cession renseignés : <b>${known.length?fmt(known.reduce((n,e)=>n+e.amount,0))+' FCFA':'Aucun'}</b> (${known.length}/${sales.length})</span></div><div class="view-switch"><button data-exit-tab="active" class="${exitTab==='active'?'active':''}">Véhicules sortis (${active.length})</button><button data-exit-tab="cancelled" class="${exitTab==='cancelled'?'active':''}">Sorties annulées (${all.length-active.length})</button></div><div class="table-wrap"><table><thead><tr><th>Véhicule</th><th>Immatriculation</th><th>Date de sortie</th><th>Motif</th><th>Bénéficiaire / acquéreur</th><th>Montant</th><th>Action</th></tr></thead><tbody>${list.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(e=>`<tr><td><span class="vehicle-name">${photo(e.vehicle)}${esc(e.vehicle.name)}</span></td><td>${esc(e.vehicle.plate)}</td><td>${date(e.date)}</td><td>${esc(e.reason)}</td><td>${showValue(e.beneficiary)}</td><td>${exitMoney(e.amount)}</td><td><button class="text-button" data-exit-detail="${esc(e.id)}">Consulter</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Aucune sortie dans cette vue.</td></tr>'}</tbody></table></div><p class="import-help">Les véhicules sortis sont exclus des compteurs, disponibilités et alertes du parc actif. Leur fiche et leur historique restent dans ce registre, distinct de la corbeille.</p></section>`;
}
function openExitForm(id=''){
 if(!state.vehicles.length)return toast('Aucun véhicule dans le parc actif.');
 const v=vehicle(id)||state.vehicles[0];pendingExitVehicle=v.id;formType='vehicle-exit';vehiclePhotoSession++;vehiclePhotoBusy=false;exitFormSession++;exitDocumentBusy=false;exitDocumentDraft=null;
 $('#dialog').classList.add('wide');$('#modalTitle').textContent='Enregistrer une sortie du parc';$('#dialog .modal-actions').style.display='flex';$('#form button[type="submit"]').textContent='Enregistrer la sortie';
 $('#fields').innerHTML=section('Véhicule et sortie',select('Véhicule *','exitVehicle',state.vehicles.map(x=>[x.id,x.name+' · '+x.plate]),v.id)+select('Motif de sortie *','exitReason',Fleet.exitReasons)+field('Date de sortie *','exitDate','date',today(),`required max="${today()}"`)+field('Bénéficiaire / acquéreur','exitBeneficiary','text','','maxlength="200"')+field('Montant de cession (FCFA)','exitAmount','number','','min="0" step="1" placeholder="Laisser vide si non renseigné"')+field('Kilométrage à la sortie','exitKm','number',v.km??'','min="0" step="1"')+field('Référence du justificatif','exitReference','text','','maxlength="120"'))+`<label class="field">Observations<textarea name="exitNotes" maxlength="2000" rows="3"></textarea></label><fieldset class="form-section"><legend>Justificatif facultatif</legend><label class="field">Joindre un PDF ou une photo<input id="exitDocumentFile" type="file" accept="application/pdf,image/jpeg,image/png,image/webp"></label><p id="exitDocumentStatus" class="import-help" role="status">Aucun fichier joint. PDF : 300 Ko maximum. Les photos sont automatiquement allégées.</p><button type="button" class="text-button" id="removeExitDocument" hidden>Retirer le justificatif</button></fieldset><div id="exitImpact" class="notice"></div><p class="import-help">Le bénéficiaire est obligatoire pour une vente / cession, une restitution ou un transfert. Une sortie retire le véhicule du parc actif tout en conservant la fiche, la photo et l’historique. Les données et justificatifs restent dans la base partagée et dans la sauvegarde JSON.</p>`;
 $('#dialog').showModal();
 const impact=()=>{const x=vehicle($('#form [name="exitVehicle"]').value);if(!x)return;const n=state.maintenance.filter(m=>m.vehicle===x.id).length,r=state.reservations.filter(a=>a.vehicle===x.id).length;$('#exitImpact').textContent=x.name+' · '+x.plate+' : '+n+' entretien(s) et '+r+' réservation(s) seront conservés dans le dossier de sortie et retirés des listes actives.';};
 $('#form [name="exitVehicle"]').onchange=e=>{pendingExitVehicle=e.target.value;$('#form [name="exitKm"]').value=vehicle(pendingExitVehicle)?.km??'';impact()};impact();bindExitDocument();
}
function bindExitDocument(){
 const session=exitFormSession;let sequence=0;
 $('#removeExitDocument').onclick=()=>{sequence++;exitDocumentBusy=false;exitDocumentDraft=null;$('#exitDocumentStatus').textContent='Aucun fichier joint.';$('#removeExitDocument').hidden=true};
 $('#exitDocumentFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;const token=++sequence;exitDocumentBusy=true;$('#exitDocumentStatus').textContent='Préparation du justificatif…';
  try{let attachment;if(file.type==='application/pdf'){
   if(file.size>300*1024)throw Error('Choisissez un PDF de 300 Ko maximum.');
   const bytes=new Uint8Array(await file.arrayBuffer());if(String.fromCharCode(...bytes.slice(0,5))!=='%PDF-')throw Error('Le fichier PDF est illisible ou invalide.');
   const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Lecture du fichier impossible.'));reader.readAsDataURL(file)});attachment={name:file.name.slice(0,200),type:'application/pdf',data};
  }else{attachment={name:file.name.replace(/\.[^.]+$/,'').slice(0,180)+'.jpg',type:'image/jpeg',data:await compactVehiclePhoto(file)}}
  if(session!==exitFormSession||sequence!==token)return;exitDocumentDraft=attachment;$('#exitDocumentStatus').textContent='Justificatif prêt : '+attachment.name;$('#removeExitDocument').hidden=false;
  }catch(error){if(session===exitFormSession&&sequence===token)$('#exitDocumentStatus').textContent=error.message+(exitDocumentDraft?' Le justificatif précédent est conservé.':'');}
  finally{if(session===exitFormSession&&sequence===token)exitDocumentBusy=false;e.target.value='';}
 };
}
function showExitDetail(id){
 const entry=(state.exitedVehicles||[]).find(e=>e.id===id);if(!entry)return;formType='exit-detail';vehiclePhotoSession++;exitFormSession++;$('#dialog').classList.add('wide');$('#modalTitle').textContent='Sortie · '+entry.vehicle.plate;$('#dialog .modal-actions').style.display='none';
 $('#fields').innerHTML=`<div class="detail-header">${photo(entry.vehicle)}<div><strong>${esc(entry.vehicle.name)}</strong><p>${esc(entry.vehicle.plate)}</p></div></div><dl class="details-grid">${[['Motif',entry.reason],['Date de sortie',date(entry.date)],['Bénéficiaire / acquéreur',entry.beneficiary],['Montant',exitMoney(entry.amount)],['Kilométrage de sortie',kmLabel(entry.km)],['Référence du justificatif',entry.reference],['Observations',entry.notes],...(entry.cancelledAt?[['Sortie annulée le',date(entry.cancelledAt)],['Motif d’annulation',entry.cancellationReason]]:[])].map(([k,v])=>`<div><dt>${k}</dt><dd>${showValue(v)}</dd></div>`).join('')}</dl><div class="detail-buttons">${entry.attachment?'<button type="button" class="secondary" id="downloadExitDocument">Télécharger le justificatif</button>':''}${!entry.cancelledAt?`<button type="button" class="secondary" data-cancel-exit="${esc(entry.id)}">Annuler la sortie et réintégrer</button>`:''}</div><h3>Fiche du véhicule à la sortie</h3><dl class="details-grid">${detailRows(entry.vehicle).map(([k,v])=>`<div><dt>${k}</dt><dd>${showValue(v)}</dd></div>`).join('')}</dl><h3>Entretiens conservés (${entry.maintenance.length})</h3><div class="table-wrap"><table><thead><tr><th>Intervention</th><th>Date</th><th>Coût</th><th>État à la sortie</th></tr></thead><tbody>${entry.maintenance.map(m=>`<tr><td>${esc(m.title)}</td><td>${date(m.date)}</td><td>${fmt(m.cost)} FCFA</td><td>${m.done?'Terminé':'Non terminé'}</td></tr>`).join('')||'<tr><td colspan="4">Aucun entretien.</td></tr>'}</tbody></table></div><h3>Réservations conservées (${entry.reservations.length})</h3><div class="table-wrap"><table><thead><tr><th>Utilisateur</th><th>Début</th><th>Fin</th><th>Motif</th></tr></thead><tbody>${entry.reservations.map(r=>`<tr><td>${esc(r.person)}</td><td>${date(r.start)}</td><td>${date(r.end)}</td><td>${esc(r.reason)}</td></tr>`).join('')||'<tr><td colspan="4">Aucune réservation.</td></tr>'}</tbody></table></div>`;
 $('#dialog').showModal();if(entry.attachment)$('#downloadExitDocument').onclick=()=>{const a=entry.attachment;const bytes=Uint8Array.from(atob(a.data.split(',')[1]),c=>c.charCodeAt(0));download(bytes,a.type,a.name)};
}
function openCancelExit(id){
 const entry=state.exitedVehicles.find(e=>e.id===id&&!e.cancelledAt);if(!entry)return;$('#dialog').close();pendingCancelExit=id;formType='cancel-exit';exitFormSession++;$('#modalTitle').textContent='Annuler la sortie · '+entry.vehicle.plate;$('#dialog .modal-actions').style.display='flex';$('#form button[type="submit"]').textContent='Annuler la sortie et réintégrer';$('#fields').innerHTML=`<p class="import-help">${esc(entry.vehicle.name)} sera réintégré avec sa fiche et son historique. La sortie restera dans l’onglet Sorties annulées.</p>`+field('Motif d’annulation *','cancellationReason','text','','required maxlength="1000"');$('#dialog').showModal();
}
const submitBeforeExits=$('#form').onsubmit;
$('#form').onsubmit=function(e){
 if(!['vehicle-exit','cancel-exit','exit-detail'].includes(formType))return submitBeforeExits.call(this,e);e.preventDefault();if(formType==='exit-detail')return;
 try{
  let candidate;if(formType==='cancel-exit'){candidate=Fleet.cancelExit(state,pendingCancelExit,$('#form [name="cancellationReason"]').value,today())}
  else{
   if(exitDocumentBusy)return toast('Patientez pendant la préparation du justificatif.');
   const values=Object.fromEntries(new FormData(this)),v=vehicle(values.exitVehicle);if(!v)return toast('Véhicule introuvable.');
   const meta={reason:values.exitReason,date:values.exitDate,beneficiary:values.exitBeneficiary.trim(),amount:values.exitAmount===''?null:Number(values.exitAmount),km:values.exitKm===''?null:Number(values.exitKm),reference:values.exitReference.trim(),notes:values.exitNotes.trim(),attachment:exitDocumentDraft};
   candidate=Fleet.recordExit(state,v.id,meta,today());
   if(!confirm('Enregistrer la sortie de '+v.name+' — '+v.plate+' ?\nMotif : '+meta.reason+'\nDate : '+date(meta.date)+'\nLe véhicule sera retiré du parc actif. Sa fiche et son historique resteront dans Sorties du parc.'))return;
  }
  const cancelling=formType==='cancel-exit';if(!applyFleetChange(candidate))return;exitFormSession++;exitDocumentBusy=false;$('#dialog').close();if(location.hash!=='#exits')location.hash='exits';else render();toast(cancelling?'Sortie annulée et véhicule réintégré.':'Sortie enregistrée. Le dossier est conservé dans Sorties du parc.');
 }catch(error){toast(error.message)}
};
function exportExitCSV(){const clean=x=>'"'+String(x??'').replace(/^[\s]*[=+@\-]/,"'$&").replace(/"/g,'""')+'"';const rows=[['Immatriculation','Marque','Modèle','Date de sortie','Motif','Bénéficiaire / acquéreur','Montant FCFA','Kilométrage de sortie','Référence','Observations','Annulée le','Motif d’annulation'],...(state.exitedVehicles||[]).map(e=>[e.vehicle.plate,e.vehicle.brand,e.vehicle.model,e.date,e.reason,e.beneficiary,e.amount,e.km,e.reference,e.notes,e.cancelledAt,e.cancellationReason])];download('\ufeff'+rows.map(r=>r.map(clean).join(';')).join('\r\n'),'text/csv;charset=utf-8','AUTO_ORYX_Sorties_'+today()+'.csv');}
document.addEventListener('click',e=>{const detail=e.target.closest('[data-exit-detail]'),out=e.target.closest('[data-exit-vehicle]'),cancel=e.target.closest('[data-cancel-exit]'),tab=e.target.closest('[data-exit-tab]');if(e.target.closest('[data-new-exit]'))openExitForm();else if(out){if($('#dialog').open)$('#dialog').close();openExitForm(out.dataset.exitVehicle)}else if(detail)showExitDetail(detail.dataset.exitDetail);else if(cancel)openCancelExit(cancel.dataset.cancelExit);else if(tab){exitTab=tab.dataset.exitTab;render()}else if(e.target.closest('[data-exit-export]'))exportExitCSV()});
const openFormBeforeExits=openForm;openForm=function(type,id=''){exitFormSession++;exitDocumentBusy=false;openFormBeforeExits(type,id);if(type==='vehicle'&&id&&vehicle(id)&&$('#dialog').open){$('#fields').insertAdjacentHTML('beforeend',`<button type="button" class="secondary" data-exit-vehicle="${esc(id)}">Enregistrer une sortie du parc</button>`);}};
const detailsBeforeExits=details;details=function(id){detailsBeforeExits(id);if(vehicle(id)&&$('#dialog').open)$('#fields .detail-buttons').insertAdjacentHTML('beforeend',`<button type="button" class="secondary" data-exit-vehicle="${esc(id)}">Enregistrer une sortie du parc</button>`);};


/* Sinistres : registre local, immobilisation et remise en service explicites. */
let accidentTab='open',accidentEditId='',accidentDocs=[],accidentBusy=false,accidentSession=0;
function accidents(){
 const all=state.accidents,list=all.filter(a=>(accidentTab==='open'?!a.closedAt:!!a.closedAt)&&(!query||[a.vehicle.name,a.vehicle.plate,a.driver,a.reference,a.garage].join(' ').toLowerCase().includes(query.toLowerCase())));
 return head('Sinistres et accidents','Déclarations, expertise, réparations et remise en service.',`<button class="primary" data-new-accident>Déclarer un accident</button>`)+`<section class="panel"><div class="view-switch"><button data-accident-tab="open" class="${accidentTab==='open'?'active':''}">En cours (${all.filter(a=>!a.closedAt).length})</button><button data-accident-tab="closed" class="${accidentTab==='closed'?'active':''}">Clôturés (${all.filter(a=>a.closedAt).length})</button></div><div class="table-wrap"><table><thead><tr><th>Véhicule</th><th>Immatriculation</th><th>Accident</th><th>Suivi</th><th>Garage</th><th>Coût estimé / réel</th><th></th></tr></thead><tbody>${list.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(a=>`<tr><td>${esc(a.vehicle.name)}</td><td>${esc(a.vehicle.plate)}</td><td>${date(a.date)}</td><td>${esc(a.closedAt?a.outcome:a.stage)}</td><td>${showValue(a.garage)}</td><td>${exitMoney(a.cost)}</td><td><button class="text-button" data-accident-detail="${esc(a.id)}">Consulter</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Aucun sinistre dans cette vue.</td></tr>'}</tbody></table></div><p class="import-help">Un sinistre ouvert immobilise le véhicule et empêche son affectation ou sa réservation. Les réservations déjà enregistrées sont conservées et doivent être replanifiées. Photos, documents et historique sont inclus dans la sauvegarde JSON.</p></section>`;
}
function openAccidentForm(id='',vehicleId=''){
 const a=state.accidents.find(a=>a.id===id);if(a?.closedAt)return toast('Ce dossier est clôturé.');
 const eligible=state.vehicles.filter(v=>!state.accidents.some(a=>!a.closedAt&&a.vehicle.id===v.id));
 if(!a&&!eligible.length)return toast('Aucun véhicule sans sinistre ouvert.');
 const v=a?vehicle(a.vehicle.id):eligible.find(v=>v.id===vehicleId)||eligible[0];if(!v)return;
 accidentSession++;vehiclePhotoSession++;exitFormSession++;accidentBusy=false;accidentEditId=id;accidentDocs=structuredClone(a?.documents||[]);formType='accident';
 $('#modalTitle').textContent=a?'Mettre à jour le sinistre · '+a.vehicle.plate:'Déclarer un accident';$('#dialog').classList.add('wide');$('#dialog .modal-actions').style.display='flex';$('#form button[type="submit"]').textContent=a?'Enregistrer le suivi':'Déclarer et immobiliser';
 $('#fields').innerHTML=(a?`<p class="notice">${esc(a.vehicle.name)} · ${esc(a.vehicle.plate)} — véhicule immobilisé.</p>`+section('Suivi du dossier',select('Étape *','stage',Fleet.accidentStages,a.stage)+field('Date du suivi *','updateDate','date',today(),`required max="${today()}" min="${a.history.at(-1).date}"`)+select('Issue si clôturé','outcome',['Remis en service','Irréparable'])+select('Statut après réparation','returnStatus',['Disponible','Affecté'])):section('Déclaration',select('Véhicule *','accidentVehicle',eligible.map(v=>[v.id,v.name+' · '+v.plate]),v.id)+field('Date de l’accident *','accidentDate','date',today(),`required max="${today()}"`)+field('Lieu *','location','text','','required maxlength="200"')+field('Conducteur','driver','text',v.userName||'','maxlength="200"'))+`<label class="field">Circonstances *<textarea name="circumstances" required maxlength="2000" rows="3"></textarea></label>`)+section('Réparation et assurance',field('Garage','garage','text',a?.garage||'','maxlength="200"')+field('Assureur','insurer','text',a?.insurer||'','maxlength="200"')+field('Référence du sinistre / constat','reference','text',a?.reference||'','maxlength="200"')+field('Coût estimé / réel (FCFA)','cost','number',a?.cost??'','min="0" step="1"'))+`<label class="field">Observations / compte rendu<textarea name="notes" maxlength="2000" rows="3">${esc(a?.notes||'')}</textarea></label><fieldset class="form-section"><legend>Photos des dégâts et documents (5 maximum)</legend><input type="file" id="accidentFile" accept="application/pdf,image/jpeg,image/png,image/webp" multiple><p class="import-help" id="accidentFileStatus" role="status">Photos allégées automatiquement. Chaque PDF : 300 Ko maximum.</p><div id="accidentFiles"></div></fieldset><p class="import-help">Pour une remise en service « Affecté », renseignez d’abord l’utilisateur dans la fiche véhicule. Un véhicule irréparable reste immobilisé : enregistrez ensuite sa mise au rebut dans Sorties du parc. Le coût est un suivi indicatif, sans écriture comptable automatique.</p>`;
 const session=accidentSession;
 const display=()=>{$('#accidentFiles').innerHTML=accidentDocs.map((d,i)=>`<div class="metric"><span>${esc(d.name)}</span><button type="button" class="text-button" data-remove-acc-doc="${i}">Retirer</button></div>`).join('');$('#accidentFiles').querySelectorAll('[data-remove-acc-doc]').forEach(b=>b.onclick=()=>{if(accidentBusy)return;accidentDocs.splice(Number(b.dataset.removeAccDoc),1);display()})};display();
 $('#accidentFile').onchange=async e=>{const files=[...e.target.files];if(accidentBusy)return;if(files.length+accidentDocs.length>5){e.target.value='';return toast('Cinq documents maximum par dossier.')}accidentBusy=true;$('#accidentFileStatus').textContent='Préparation des fichiers…';
  try{const docs=[];for(const f of files){let data,type,name;if(f.type==='application/pdf'){if(f.size>300*1024||new TextDecoder().decode((await f.arrayBuffer()).slice(0,5))!=='%PDF-')throw Error('PDF invalide ou supérieur à 300 Ko.');data=await new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=()=>no(Error('Lecture impossible.'));r.readAsDataURL(f)});type='application/pdf';name=f.name.slice(0,200);}else{data=await compactVehiclePhoto(f);type='image/jpeg';name=f.name.replace(/\.[^.]+$/,'').slice(0,180)+'.jpg';}docs.push({name,type,data});}if(session!==accidentSession||formType!=='accident')return;accidentDocs.push(...docs);display();$('#accidentFileStatus').textContent='Fichiers prêts : '+accidentDocs.length;}
  catch(error){if(session===accidentSession&&formType==='accident')$('#accidentFileStatus').textContent=error.message;}finally{if(session===accidentSession){accidentBusy=false;e.target.value='';}}
 };$('#dialog').showModal();
}
function showAccidentDetail(id){
 const a=state.accidents.find(a=>a.id===id);if(!a)return;accidentSession++;formType='accident-detail';$('#modalTitle').textContent='Sinistre · '+a.vehicle.plate;$('#dialog').classList.add('wide');$('#dialog .modal-actions').style.display='none';
 $('#fields').innerHTML=`<div class="detail-header">${photo(a.vehicle)}<strong>${esc(a.vehicle.name)} · ${esc(a.vehicle.plate)}</strong></div><dl class="details-grid">${[['Date',date(a.date)],['Lieu',a.location],['Conducteur',a.driver],['Circonstances',a.circumstances],['Suivi',a.stage],['Garage',a.garage],['Assureur',a.insurer],['Référence',a.reference],['Coût estimé / réel',exitMoney(a.cost)],['Observations',a.notes],['Issue',a.outcome],['Clôture',a.closedAt?date(a.closedAt):'En cours']].map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${showValue(v)}</dd></div>`).join('')}</dl><h3>Photos et documents</h3><div class="accident-documents">${a.documents.map((d,i)=>`<div>${d.type==='image/jpeg'?`<img src="${esc(d.data)}" alt="Photo des dégâts ${i+1}">`:''}<button type="button" class="secondary" data-acc-doc="${i}">${esc(d.name)} · Télécharger</button></div>`).join('')||'<p>Aucun document joint.</p>'}</div><h3>Historique du suivi</h3>${a.history.map(h=>`<p>${date(h.date)} · <b>${esc(h.stage)}</b> — ${esc(h.note)}</p>`).join('')}<div class="detail-buttons">${!a.closedAt?`<button type="button" class="primary" data-accident-edit="${esc(a.id)}">Mettre à jour / clôturer</button>`:''}${a.outcome==='Irréparable'&&vehicle(a.vehicle.id)?`<button type="button" class="secondary" data-accident-scrap="${esc(a.vehicle.id)}">Enregistrer la mise au rebut</button>`:''}</div>`;
 $('#fields').querySelectorAll('[data-acc-doc]').forEach(b=>b.onclick=()=>{const d=a.documents[Number(b.dataset.accDoc)],bytes=Uint8Array.from(atob(d.data.split(',')[1]),c=>c.charCodeAt(0));download(bytes,d.type,d.name)});$('#dialog').showModal();
}
const submitBeforeAccidents=$('#form').onsubmit;
$('#form').onsubmit=function(e){if(formType!=='accident')return submitBeforeAccidents.call(this,e);e.preventDefault();if(accidentBusy)return toast('Patientez pendant la préparation des fichiers.');const f=Object.fromEntries(new FormData(this));const common={garage:f.garage.trim(),insurer:f.insurer.trim(),reference:f.reference.trim(),cost:f.cost===''?null:Number(f.cost),notes:f.notes.trim(),documents:accidentDocs};try{let next;if(accidentEditId){next=Fleet.updateAccident(state,accidentEditId,{...common,stage:f.stage,updateDate:f.updateDate,outcome:f.outcome,returnStatus:f.returnStatus,note:f.notes.trim()},today());}else{if(!confirm('Déclarer cet accident et immobiliser le véhicule ? Vérifiez ses réservations en cours.'))return;next=Fleet.recordAccident(state,f.accidentVehicle,{...common,date:f.accidentDate,location:f.location.trim(),driver:f.driver.trim(),circumstances:f.circumstances.trim()},today());}if(!applyFleetChange(next))return;accidentSession++;$('#dialog').close();if(location.hash!=='#accidents')location.hash='accidents';else render();toast('Dossier du sinistre enregistré.');}catch(error){toast(error.message)}};
document.addEventListener('click',e=>{const detail=e.target.closest('[data-accident-detail]'),edit=e.target.closest('[data-accident-edit]'),tab=e.target.closest('[data-accident-tab]'),declare=e.target.closest('[data-declare-accident]');if(e.target.closest('[data-new-accident]'))openAccidentForm();else if(detail)showAccidentDetail(detail.dataset.accidentDetail);else if(edit){$('#dialog').close();openAccidentForm(edit.dataset.accidentEdit)}else if(tab){accidentTab=tab.dataset.accidentTab;render()}else if(declare){$('#dialog').close();openAccidentForm('',declare.dataset.declareAccident)}});
const detailsBeforeAccidents=details;details=function(id){detailsBeforeAccidents(id);if(vehicle(id)&&$('#dialog').open){const a=state.accidents.find(a=>!a.closedAt&&a.vehicle.id===id);$('#fields .detail-buttons').insertAdjacentHTML('beforeend',a?`<button type="button" class="secondary" data-accident-detail="${esc(a.id)}">Consulter le sinistre ouvert</button>`:`<button type="button" class="secondary" data-declare-accident="${esc(id)}">Déclarer un accident</button>`);}};
const renderBeforeAccidents=render;render=function(){renderBeforeAccidents();if(['dashboard','vehicles','reports'].includes(page)){const count=state.vehicles.filter(v=>v.status==='Accidenté / Immobilisé').length;if(count){const n=document.createElement('a');n.href='#accidents';n.className='notice accident-notice';n.textContent=count+' véhicule(s) accidenté(s) / immobilisé(s) · Consulter les sinistres';$('#main').insertBefore(n,$('#main').children[1]||null);}}};
document.addEventListener('click',e=>{const b=e.target.closest('[data-accident-scrap]');if(b){$('#dialog').close();openExitForm(b.dataset.accidentScrap);$('#form [name="exitReason"]').value='Mise au rebut';}});

